#!/usr/bin/env python3
"""Generate biped_tree.urdf: a TRON1-like tree (base + two legs of abad x, hip y, knee -y, wheel y) for the floating
base tests. Every link has a CoM offset and a principal inertia rotated by its <inertial><origin rpy>, so that the
comparison also checks how the inertia is rotated into the link frame. Values are not those of a real robot."""
from pathlib import Path

links = [('base_link', None, 9.6, (0.046, 0.001, -0.164), (0.10, -0.20, 0.05), (0.14, 0.11, 0.09))]
for side, s in (('L', 1), ('R', -1)):
    links += [
        (f'abad_{side}', (f'abad_{side}_joint', 'base_link', (0.056, 0.105*s, -0.260), (0.0, 0.0, 0.0), (1, 0, 0), 'revolute'),
         1.47, (-0.070, 0.045*s, 0.001), (0.3, 0.1*s, -0.2), (0.0025, 0.0021, 0.0014)),
        (f'hip_{side}', (f'hip_{side}_joint', f'abad_{side}', (-0.077, 0.0205*s, 0.0), (0.0, 0.05, 0.0), (0, 1, 0), 'revolute'),
         2.30, (-0.029, -0.048*s, -0.040), (-0.2, 0.4, 0.1*s), (0.023, 0.020, 0.004)),
        (f'knee_{side}', (f'knee_{side}_joint', f'hip_{side}', (-0.150, -0.0205*s, -0.260), (0.0, 0.0, 0.1*s), (0, -1, 0), 'revolute'),
         1.49, (0.119, 0.011*s, -0.204), (0.15, -0.3, 0.25), (0.018, 0.016, 0.003)),
        (f'wheel_{side}', (f'wheel_{side}_joint', f'knee_{side}', (0.150, 0.0435*s, -0.260), (0.0, 0.0, 0.0), (0, 1, 0), 'continuous'),
         1.08, (0.0, 0.008*s, 0.0), (0.05, 0.0, 0.3), (0.0052, 0.0097, 0.0052)),
    ]

f = lambda v: ' '.join(f'{x:g}' for x in v)
out = ['<?xml version="1.0"?>',
       '<!-- Floating-base test fixture: TRON1-like tree, base + two legs (abad x, hip y, knee -y, wheel y).',
       '     Every link has a CoM offset and a principal inertia rotated by its inertial frame. Generated by make_biped_tree.py. -->',
       '<robot name="biped_tree">']
for name, joint, m, com, rpy, I in links:
    out += [f'  <link name="{name}">', '    <inertial>', f'      <origin xyz="{f(com)}" rpy="{f(rpy)}"/>', f'      <mass value="{m}"/>',
            f'      <inertia ixx="{I[0]}" ixy="0" ixz="0" iyy="{I[1]}" iyz="0" izz="{I[2]}"/>', '    </inertial>', '  </link>']
for name, joint, *_ in links:
    if joint is None:
        continue
    jn, parent, xyz, rpy, axis, jt = joint
    limit = '' if jt == 'continuous' else '\n    <limit lower="-2" upper="2" effort="80" velocity="15"/>'
    out += [f'  <joint name="{jn}" type="{jt}">', f'    <origin xyz="{f(xyz)}" rpy="{f(rpy)}"/>', f'    <parent link="{parent}"/>',
            f'    <child link="{name}"/>', f'    <axis xyz="{f(axis)}"/>{limit}', '  </joint>']
out.append('</robot>')
(Path(__file__).parent / 'biped_tree.urdf').write_text('\n'.join(out) + '\n')
